  ('cal:wiki-2020-draft', 'REFERENCE_DATABASE', '2020 Major League Baseball draft', 'Wikipedia', 'https://en.wikipedia.org/wiki/2020_Major_League_Baseball_draft', null, date '2026-10-19', 'AGGREGATOR', 'Fetched directly. June 10-11, 2020; held remotely from MLB Network studios in Secaucus (originally planned for Omaha); 5 rounds, 160 selections; March 26, 2020 MLB-MLBPA agreement allowed shortening.'),
  ('cal:mlb-2020-schedule', 'OFFICIAL_LEAGUE', 'MLB announces 2020 Draft schedule', 'MLB.com', 'https://www.mlb.com/news/2020-mlb-draft-schedule', null, date '2026-10-19', 'OFFICIAL', 'Seen via search snippet. June 10 first 37 picks (Round 1 + CB Round A); June 11 from Round 2 (pick 38) through the fifth and final round; undrafted players capped at $20,000 each.'),
  ('cal:wiki-2021-draft', 'REFERENCE_DATABASE', '2021 Major League Baseball draft', 'Wikipedia', 'https://en.wikipedia.org/wiki/2021_Major_League_Baseball_draft', null, date '2026-10-19', 'AGGREGATOR', 'Fetched directly. July 11-13, 2021, Bellco Theatre Denver; 20 rounds, 612 selections; moved from Atlanta on April 2, 2021; 20 rounds chosen under March 26, 2020 agreement.'),
  ('cal:mlb-2021-draft-coverage', 'OFFICIAL_LEAGUE', '2021 MLB Draft Day 2 / Day 3 complete coverage', 'MLB.com', 'https://www.mlb.com/news/2021-mlb-draft-day-3-complete-coverage', null, date '2026-10-19', 'OFFICIAL', 'Seen via search snippets (Day 1/2/3 coverage pages and mlb.com/draft/2021). Day 1 Sun July 11 first 36 picks; Day 2 Mon July 12 Rounds 2-10; Day 3 Tue July 13 Rounds 11-20; pools in a Draft reduced to 20 rounds from the 40 called for in the CBA.'),
  ('cal:wiki-2022-draft', 'REFERENCE_DATABASE', '2022 Major League Baseball draft', 'Wikipedia', 'https://en.wikipedia.org/wiki/2022_Major_League_Baseball_draft', null, date '2026-10-19', 'AGGREGATOR', 'Fetched directly. July 17-19, 2022, L.A. Live Los Angeles; 616 selections in 20 rounds; summarizes March 10, 2022 CBA draft changes (lottery from 2023, permanent 20 rounds, combine, draft-and-follow).'),
  ('cal:mlb-2022-draft-schedule', 'OFFICIAL_LEAGUE', 'MLB Draft overview and schedule 2022 / 2022 MLB Draft Day 2 overview and schedule', 'MLB.com', 'https://www.mlb.com/news/mlb-draft-overview-and-schedule-2022', null, date '2026-10-19', 'OFFICIAL', 'Seen via search snippets. Day 1 Sun July 17 Rounds 1-2 + comp/CB picks (80 players); Day 2 Mon July 18 Rounds 3-10; Day 3 Tue July 19 Rounds 11-20.'),
  ('cal:mlb-cba-draft-changes-2022', 'OFFICIAL_LEAGUE', 'Here''s how the new CBA impacts the Draft', 'MLB.com', 'https://www.mlb.com/news/draft-rule-changes-with-new-cba', null, date '2026-10-19', 'OFFICIAL', '403 on direct fetch; seen via search snippets. Lottery for first six picks from 2023; draft remains 20 rounds; ineligible clubs cannot pick above 10th; 75% slot guarantee for top-300 prospects who take pre-draft physical.'),
  ('cal:mlb-ppi-faq', 'OFFICIAL_LEAGUE', 'Prospect Promotion Incentive (PPI) FAQ', 'MLB.com', 'https://www.mlb.com/news/prospect-promotion-incentive-faq', null, date '2026-10-19', 'OFFICIAL', 'Seen via search snippet. PPI created in 2022 CBA; picks awarded when an eligible rookie-status player wins ROY or finishes top-3 in MVP/Cy Young pre-arbitration; max one per club per year.'),
  ('cal:wiki-2023-draft', 'REFERENCE_DATABASE', '2023 Major League Baseball draft', 'Wikipedia', 'https://en.wikipedia.org/wiki/2023_Major_League_Baseball_draft', null, date '2026-10-19', 'AGGREGATOR', 'Fetched directly. July 9-11, 2023, Lumen Field Seattle; 20 rounds, 614 selections; inaugural lottery Dec 6, 2022 in San Diego (Pirates won); first PPI pick (Mariners, No. 29).'),
