  ('cal:fangraphs-rule-changes-intl', 'NEWS_REPORT', 'Rule Changes In The International Market', 'FanGraphs', 'https://blogs.fangraphs.com/?p=91278', null, date '2026-10-19', 'REPUTABLE_SECONDARY', 'Search snippet: original 2012-13 penalty table: 75% tax at 0-5%, ... 100% tax + $250K cap at 15%+.'),
  ('cal:sbd-2014-yankees', 'NEWS_REPORT', 'SBD Jan 2, 2014 Franchises (Yankees)', 'Sports Business Daily', 'https://www.sportsbusinessdaily.com/Daily/Issues/2014/01/02/Franchises/Yankees.aspx', date '2014-01-02', date '2026-10-19', 'REPUTABLE_SECONDARY', 'Search snippet: maximum penalty (15%+ over) = no bonus above $300K for next two years.'),
  ('cal:si-lockout-signing-day-2022', 'NEWS_REPORT', 'MLB International Signing Day Not Be Affected by Lockout', 'Sports Illustrated (Guardians On SI)', 'https://www.si.com/mlb/guardians/onsi/news/mlb-international-signing-day-not-affected-by-lockout', null, date '2026-10-19', 'REPUTABLE_SECONDARY', 'Search snippet: Jan 15, 2022 signing day proceeds despite MLB lockout; minor league contracts not part of lockout.'),
  ('cal:mlbtr-period-opens-2022', 'NEWS_REPORT', 'International Signing Period Opens Today', 'MLB Trade Rumors (TC Zencka)', 'https://mlbtraderumors.com/2022/01/international-signing-period-opens-today.html', date '2022-01-15', date '2026-10-19', 'REPUTABLE_SECONDARY', 'Fetched. Calls it the 2021-22 period; opens Jan 15 2022; closes Dec 15 2022; second consecutive Jan 15 opening.'),
  ('cal:mlb-signing-day-2021-22', 'OFFICIAL_LEAGUE', 'Where top int''l prospects are signing (2021-22)', 'MLB.com', 'https://www.mlb.com/news/mlb-international-prospects-signing-day-2021-22', date '2022-01-15', date '2026-10-19', 'OFFICIAL', 'Search snippet: began Jan 15, 2022, runs through Dec 15, 2022. Date inferred.'),
  ('cal:ap-intl-draft-rejected-2022', 'NEWS_REPORT', 'MLB players'' union rejects international draft proposal', 'Associated Press (Ronald Blum), via News4Jax', 'https://www.news4jax.com/sports/2022/07/25/mlb-players-union-rejects-international-draft-proposal/', date '2022-07-25', date '2026-10-19', 'REPUTABLE_SECONDARY', 'Fetched. Union rejected MLB''s final international-draft offer ~8 hours before July 25 deadline; QO/draft-pick compensation retained; 2022-23 pool stays $167M per side letter, grows with revenue from 2023-24.'),
  ('cal:dodgerblue-2022-23-pool', 'NEWS_REPORT', 'Dodgers Bonus Pool Money For 2022-23 International Signing Period', 'Dodger Blue (Blake Williams)', 'https://dodgerblue.com/dodgers-bonus-pool-money-for-2022-23-international-signing-period/2023/01/15/amp/', date '2023-01-15', date '2026-10-19', 'OTHER', 'Fetched. Names the calendar-2023 period ''2022-23''; began Sunday Jan 15, runs through Dec 15.'),
  ('cal:ba-2023-pools', 'NEWS_REPORT', 'Top 2023 MLB International Prospects And Bonus Pools For Every Team', 'Baseball America', 'https://www.baseballamerica.com/?p=47855', null, date '2026-10-19', 'REPUTABLE_SECONDARY', 'Search snippet only: 2023 pools, runs through Dec. 15, 2023.'),
  ('cal:mlbtr-period-opens-2024', 'NEWS_REPORT', 'International Signing Period Opens (Jan 15 2024)', 'MLB Trade Rumors', 'https://www.mlbtraderumors.com/page/840', date '2024-01-15', date '2026-10-19', 'REPUTABLE_SECONDARY', 'Archive listing page; search snippet: period opened Jan 15 2024 and technically runs until Dec 15.'),
  ('cal:mlb-top50-2024', 'OFFICIAL_LEAGUE', 'Here are the Top 50 international prospects for the 2024 signing period', 'MLB.com', 'https://www.mlb.com/news/the-top-mlb-international-prospects-for-2023-24', null, date '2026-10-19', 'OFFICIAL', 'Search snippet: 2024 period starts Jan. 15 and ends Dec. 15. URL slug uses ''2023-24''.'),
  ('cal:thescore-sasaki-2025', 'NEWS_REPORT', 'Manfred expects Sasaki to sign in January as part of 2025 class', 'theScore (Simon Sharkey-Gotlieb)', 'https://thescore.com/news/3134600', null, date '2026-10-19', 'REPUTABLE_SECONDARY', 'Fetched (no date shown; ~Nov 2024). 2024 period officially ends Dec 15; no signings Dec 15 2024 - Jan 15 2025.'),
  ('cal:mlb-signing-day-2025', 'OFFICIAL_LEAGUE', 'International signing period is open! Here''s where top prospects are going', 'MLB.com', 'https://www.mlb.com/news/mlb-international-prospects-signing-day-2025', date '2025-01-15', date '2026-10-19', 'OFFICIAL', 'Search snippet: eligible to sign between Jan. 15 and Dec. 15.'),
  ('cal:cbs-ifa-2025', 'NEWS_REPORT', 'MLB international free agency: Top non-Roki Sasaki players, bonus pools, more', 'CBS Sports', 'https://www.cbssports.com/mlb/news/mlb-international-free-agency-top-non-roki-sasaki-players-bonus-pools-more-as-mets-land-5m-ifa-prospect', null, date '2026-10-19', 'REPUTABLE_SECONDARY', 'Search snippet: period confined to a single calendar year, Jan. 15 to Dec. 15; 60% pool trade cap; system remains through at least 2026.'),
  ('cal:cbs-ifa-history-claim', 'NEWS_REPORT', 'CBS Sports international signing period explainer(s) (2023/2024/2026)', 'CBS Sports', 'https://www.cbssports.com/mlb/news/mlb-international-signing-period-top-players-bonus-pools-what-else-to-know-as-padres-land-no-1-prospect/', null, date '2026-10-19', 'REPUTABLE_SECONDARY', 'Fetch 429. Search snippet: period ''used to run from July 2 to June 25''; Jan 15 start made permanent. June 25 conflicts with all other sources (June 15).'),
  ('cal:mlb-signing-day-2026', 'OFFICIAL_LEAGUE', 'International signing period is open: Here''s where top prospects are going (2026)', 'MLB.com', 'https://www.mlb.com/pirates/news/mlb-international-prospects-signing-day-2026', date '2026-01-15', date '2026-10-19', 'OFFICIAL', 'Search snippet: Jan 15, 2026 opening for Class of 2026; window Jan 15 - Dec 15. Date inferred.'),
  ('cal:cbs-ifa-2026', 'NEWS_REPORT', 'MLB international free agency opens: Top prospects to know, bonus pools and more for the 2026 signing period', 'CBS Sports', 'https://www.cbssports.com/mlb/news/mlb-international-free-agency-top-prospects-bonus-pools/', null, date '2026-10-19', 'REPUTABLE_SECONDARY', 'Fetch failed (cert/429). Search snippet: 2026 period Jan 15 - Dec 15.'),
  ('cal:kosa-cba-proposal-2026', 'NEWS_REPORT', 'MLB proposes sweeping changes to draft and international player signing process in CBA negotiations', 'KOSA First Alert 7 (Gray Local Media, Jensen Young)', 'https://www.firstalert7.com/2026/06/19/mlb-proposes-sweeping-changes-draft-international-player-signing-process-cba-negotiations/', date '2026-06-18', date '2026-10-19', 'REPUTABLE_SECONDARY', 'Fetched. MLB proposed international draft w/ $200M hard pool, min age 18; MLBPA says first draft no earlier than Sept 2027; CBA ends Dec 1 2026; ''Nothing regarding these proposals would change this year''s processes.'' Search snippets attribute original reporting to ESPN (Alden Gonzalez); not independently fetched.')
insert into public.rules_eras (rules_era_key, label, effective_from, effective_to, summary, source_id) values
  ('DRAFT_CBA_2012_2016', 'Draft: 2012-2016 Basic Agreement', null, date '2016-12-01', 'Signing-bonus pools for the first 10 rounds with tax / pick-forfeiture penalties, Competitive Balance rounds, 40 rounds. Governed the 2015 and 2016 drafts. Effective start not established from an acceptable source.', (select id from public.sources where source_key = 'cal:sbd-2011-cba')),
  ('DRAFT_CBA_2017_2021', 'Draft: 2017-2021 Basic Agreement', date '2016-12-01', date '2021-12-01', '40-round draft 2017-2019. The March 26, 2020 pandemic agreement let MLB hold a 5-round 2020 draft (remote, $20,000 cap on undrafted signings) and a 20-round 2021 draft moved to July / All-Star week.', (select id from public.sources where source_key = 'cal:mlb-2016-tentative-cba')),
  ('DRAFT_CBA_2022_2026', 'Draft: 2022-2026 Basic Agreement', date '2022-03-10', date '2026-12-01', '20 rounds made permanent; draft combine; draft lottery for the top six picks from 2023; Prospect Promotion Incentive picks. Governed the 2022-2026 drafts.', (select id from public.sources where source_key = 'cal:mlb-cba-draft-changes-2022')),
  ('INTL_CBA_2012_2016', 'International: 2012-2016 Basic Agreement', date '2012-07-02', date '2017-06-15', 'Soft-capped bonus pools with tiered overage tax and later per-player bonus limits. Tier details changed during the agreement and sources disagree on them; confirm against the CBA text before relying on tiers. Covers the 2012-13 through 2016-17 periods.', (select id from public.sources where source_key = 'cal:mlb-teams-dictate-market-2015')),
  ('INTL_CBA_2017_2021', 'International: 2017-2021 Basic Agreement', date '2017-07-02', date '2021-12-01', 'Hard-capped bonus pools from 2017-18; exemption raised to age 25 with 6 foreign professional seasons. Pandemic changes: 2019-20 extended to Oct 15, 2020; 2020-21 moved to Jan 15 - Dec 15, 2021.', (select id from public.sources where source_key = 'cal:fangraphs-j2-primer-2017')),
  ('INTL_CBA_2022_2026', 'International: 2022-2026 Basic Agreement', date '2022-03-10', date '2026-12-01', 'Hard-capped pools continue with Jan 15 - Dec 15 periods. An international draft was proposed but the union rejected MLB''s final offer on July 25, 2022. The agreement expires Dec 1, 2026, before the 2026 period''s scheduled close.', (select id from public.sources where source_key = 'cal:ap-intl-draft-rejected-2022'))
insert into public.drafts (draft_key, draft_year, draft_kind, start_date, end_date, total_rounds, structure_note, source_id, rules_era_id) values
  ('2015-JUNE_AMATEUR', 2015, 'JUNE_AMATEUR', date '2015-06-08', date '2015-06-10', 40, 'Secaucus, NJ (MLB Network Studio 42). Day 1 June 8: Round 1 through Competitive Balance Round B; Day 2 June 9: Rounds 3-10; Day 3 June 10: Rounds 11-40. 1,215 players chosen in 40 rounds plus two CB rounds and one supplemental (compensation) round.',
   (select id from public.sources where source_key = 'cal:mlb-2015-draft-order'), (select id from public.rules_eras where rules_era_key = 'DRAFT_CBA_2012_2016')),
  ('2016-JUNE_AMATEUR', 2016, 'JUNE_AMATEUR', date '2016-06-09', date '2016-06-11', 40, 'Secaucus, NJ. Day 1 Thu June 9 (Round 1 through CB rounds / Round 2); rounds 3-10 completed Fri June 10; Rounds 11-40 by conference call Sat June 11 (Saturday date inferred from ''after Friday''s completion'' plus Wikipedia June 9-11 range). 1,216 players in 40 rounds and two Competitive Balance Lottery rounds. Last draft under the 2012-2016 CBA.',
   (select id from public.sources where source_key = 'cal:mlb-2016-completes'), (select id from public.rules_eras where rules_era_key = 'DRAFT_CBA_2012_2016')),
  ('2017-JUNE_AMATEUR', 2017, 'JUNE_AMATEUR', date '2017-06-12', date '2017-06-14', 40, 'Secaucus, NJ. Day 1 Mon June 12 (Round 1, CB A, Round 2, CB B - 75 picks streamed); Day 2 Tue June 13 Rounds 3-10; Day 3 Wed June 14 Rounds 11-40. 1,215 players. First draft under the 2017-2021 CBA. Cardinals forfeited picks 56 and 75 to Astros (hacking penalty).',
   (select id from public.sources where source_key = 'cal:mlb-2017-coverage-begins'), (select id from public.rules_eras where rules_era_key = 'DRAFT_CBA_2017_2021')),
  ('2018-JUNE_AMATEUR', 2018, 'JUNE_AMATEUR', date '2018-06-04', date '2018-06-06', 40, 'Secaucus, NJ. Day 1 Mon June 4 (first 43 picks on MLB Network, rest of Day 1 online); Day 2 Tue June 5 Rounds 3-10; Day 3 Wed June 6 Rounds 11-40. 1,214 players. Signing deadline July 6.',
   (select id from public.sources where source_key = 'cal:mlb-2018-completes'), (select id from public.rules_eras where rules_era_key = 'DRAFT_CBA_2017_2021')),
  ('2019-JUNE_AMATEUR', 2019, 'JUNE_AMATEUR', date '2019-06-03', date '2019-06-05', 40, 'Secaucus, NJ. Day 1 Mon June 3 (first 41 picks through CB Round A on MLB Network; Round 2 / CB B streamed after); Day 2 Tue June 4 Rounds 3-10; Day 3 Wed June 5 Rounds 11-40. 1,217 players in 40 rounds, two compensation rounds, two CB rounds. Last 40-round draft.',
   (select id from public.sources where source_key = 'cal:mlb-2019-details'), (select id from public.rules_eras where rules_era_key = 'DRAFT_CBA_2017_2021')),
  ('2020-JUNE_AMATEUR', 2020, 'JUNE_AMATEUR', date '2020-06-10', date '2020-06-11', 5, 'Pandemic-shortened. Held remotely from MLB Network studios in Secaucus (originally planned for Omaha with the College World Series). Day 1 June 10: first 37 picks (Round 1 + CB Round A); Day 2 June 11: Round 2 (pick 38) through Round 5. 160 selections. Shortening permitted by the March 26, 2020 MLB-MLBPA agreement (under the 2017-2021 CBA). Undrafted signings capped at $20,000 each (per MLB.com).',
   (select id from public.sources where source_key = 'cal:mlb-2020-schedule'), (select id from public.rules_eras where rules_era_key = 'DRAFT_CBA_2017_2021')),
  ('2021-JUNE_AMATEUR', 2021, 'JUNE_AMATEUR', date '2021-07-11', date '2021-07-13', 20, 'First draft moved to July / All-Star week (All-Star Game July 13). Relocated from Atlanta to Denver (Bellco Theatre) after April 2, 2021 decision. Day 1 Sun July 11: first 36 picks; Day 2 Mon July 12: Rounds 2-10; Day 3 Tue July 13: Rounds 11-20. 612 selections. Reduced to 20 rounds under the March 26, 2020 agreement while the 2017-2021 CBA (which called for 40) was still in force; 20 rounds made permanent by the 2022 CBA.',
   (select id from public.sources where source_key = 'cal:mlb-2021-draft-coverage'), (select id from public.rules_eras where rules_era_key = 'DRAFT_CBA_2017_2021')),
  ('2022-JUNE_AMATEUR', 2022, 'JUNE_AMATEUR', date '2022-07-17', date '2022-07-19', 20, 'Los Angeles (Xbox Plaza at L.A. Live), All-Star week. Day 1 Sun July 17: Rounds 1-2 plus comp/CB picks (80 players); Day 2 Mon July 18: Rounds 3-10; Day 3 Tue July 19: Rounds 11-20. 616 selections. First draft under the March 10, 2022 CBA: 20 rounds permanent, draft combine, 75% slot guarantee for top-300 prospects who take physicals, draft-and-follow for post-10th-round picks; lottery deferred to 2023. Signing deadline Aug 1.',
   (select id from public.sources where source_key = 'cal:mlb-2022-draft-schedule'), (select id from public.rules_eras where rules_era_key = 'DRAFT_CBA_2022_2026')),
  ('2023-JUNE_AMATEUR', 2023, 'JUNE_AMATEUR', date '2023-07-09', date '2023-07-11', 20, 'Seattle (Lumen Field), All-Star week. Day 1 Sun July 9: Rounds 1-2; Day 2 Mon July 10: Rounds 3-10; Day 3 Tue July 11: Rounds 11-20. 614 selections. First draft with a lottery (held Dec 6, 2022, San Diego; Pirates won No. 1; lottery set top six picks). First PPI pick (Mariners, No. 29, for Julio Rodriguez''s 2022 AL ROY).',
   (select id from public.sources where source_key = 'cal:mlb-2023-draft-schedule'), (select id from public.rules_eras where rules_era_key = 'DRAFT_CBA_2022_2026')),
  ('2024-JUNE_AMATEUR', 2024, 'JUNE_AMATEUR', date '2024-07-14', date '2024-07-16', 20, 'Fort Worth, TX (Cowtown Coliseum), All-Star week (game in Arlington). Day 1 Sun July 14: first 74 picks (Rounds 1-2 + comp/CB); Day 2 Mon July 15: Rounds 3-10 (from pick 75); Day 3 Tue July 16: Rounds 11-20 (from pick 316). 615 selections. Lottery Dec 5, 2023 Nashville (Guardians). PPI picks 31 (ARI) and 32 (BAL).',
   (select id from public.sources where source_key = 'cal:mlb-2024-draft-schedule'), (select id from public.rules_eras where rules_era_key = 'DRAFT_CBA_2022_2026')),
  ('2025-JUNE_AMATEUR', 2025, 'JUNE_AMATEUR', date '2025-07-13', date '2025-07-14', 20, 'First two-day format. Coca-Cola Roxy at The Battery Atlanta (Cumberland, GA), All-Star week. Day 1 Sun July 13: first 105 picks (through Round 3); Day 2 Mon July 14: Rounds 4-20. 615 selections. Lottery Dec 10, 2024 Dallas (Nationals). PPI pick 28 (KC).',
   (select id from public.sources where source_key = 'cal:mlb-2025-draft-details'), (select id from public.rules_eras where rules_era_key = 'DRAFT_CBA_2022_2026')),
  ('2026-JUNE_AMATEUR', 2026, 'JUNE_AMATEUR', date '2026-07-11', date '2026-07-12', 20, 'Philadelphia (Pennsylvania Convention Center), All-Star week. Two days: Day 1 Sat July 11: Rounds 1-4 (picks 1-135; picks 1-10 on NBC/Peacock); Day 2 Sun July 12: Rounds 5-20. 613 selections. Lottery Dec 9, 2025 Orlando (White Sox; COL, WSH, LAA ineligible). PPI picks to ATL (26) and HOU (28). Last draft under the 2022-2026 CBA (expires Dec 1, 2026). Round count is from MLB.com search snippets plus Wikipedia''s ''rounds two through 20''; MLB.com pages could not be fetched directly.',
   (select id from public.sources where source_key = 'cal:mlb-2026-draft-schedule'), (select id from public.rules_eras where rules_era_key = 'DRAFT_CBA_2022_2026'))
insert into public.international_signing_periods (period_key, label, start_date, end_date, rules_note, timing_note, source_id, rules_era_id) values
  ('2014-15', '2014-15 international signing period', date '2014-07-02', date '2015-06-15', 'CBA_2012_2016', 'Standard July 2 - June 15 window; closed June 16 - July 1.',
   (select id from public.sources where source_key = 'cal:mlb-clubs-agree-2014'), (select id from public.rules_eras where rules_era_key = 'INTL_CBA_2012_2016')),
  ('2015-16', '2015-16 international signing period', date '2015-07-02', date '2016-06-15', 'CBA_2012_2016', 'Standard window.',
   (select id from public.sources where source_key = 'cal:mlb-cardinals-2015-16-open'), (select id from public.rules_eras where rules_era_key = 'INTL_CBA_2012_2016')),
  ('2016-17', '2016-17 international signing period', date '2016-07-02', date '2017-06-15', 'CBA_2012_2016', 'Last period under soft-cap/tax system; the 2016 CBA (agreed Dec 2016) applied its hard caps starting with 2017-18, so this period kept old rules.',
   (select id from public.sources where source_key = 'cal:mlb-primer-2016'), (select id from public.rules_eras where rules_era_key = 'INTL_CBA_2012_2016')),
  ('2017-18', '2017-18 international signing period', date '2017-07-02', date '2018-06-15', 'CBA_2017_2021', 'First hard-capped period under the 2016 CBA.',
   (select id from public.sources where source_key = 'cal:mlb-tracker-2017'), (select id from public.rules_eras where rules_era_key = 'INTL_CBA_2017_2021')),
  ('2018-19', '2018-19 international signing period', date '2018-07-02', date '2019-06-15', 'CBA_2017_2021', 'Last fully normal July 2 - June 15 period.',
   (select id from public.sources where source_key = 'cal:mlb-july2-tracker-2018'), (select id from public.rules_eras where rules_era_key = 'INTL_CBA_2017_2021')),
  ('2019-20', '2019-20 international signing period', date '2019-07-02', date '2020-10-15', 'CBA_2017_2021', 'Originally scheduled to end 2020-06-15. Because of COVID-19 it was extended to Oct 15, 2020 at 5 pm ET. A transaction freeze blocked signings for part of the extension; once it lifted, clubs could use leftover 2019-20 pool space.',
   (select id from public.sources where source_key = 'cal:mlb-2019-20-roundup'), (select id from public.rules_eras where rules_era_key = 'INTL_CBA_2017_2021')),
  ('2020-21', '2020-21 international signing period', date '2021-01-15', date '2021-12-15', 'CBA_2017_2021', 'Moved for financial reasons during the pandemic: it was due to open July 2, 2020 and opened Jan 15, 2021 instead, running to Dec 15, 2021 at 5 pm ET. This was the first calendar-year window. Eligibility was unchanged (players turning 16 by Aug 31, 2020), and pool slots could not be traded in 2020 or 2021. There is no separate ''2021'' period: the 2020-21 period covers calendar 2021.',
   (select id from public.sources where source_key = 'cal:mlb-covid-intl-periods-2020'), (select id from public.rules_eras where rules_era_key = 'INTL_CBA_2017_2021')),
  ('2022', '2022 international signing period (officially styled ''2021-22'')', date '2022-01-15', date '2022-12-15', 'CBA_2017_2021', 'MLB and MLBTR call this the ''2021-22'' period. It opened Jan 15, 2022 during the MLB lockout (Dec 2, 2021 - Mar 10, 2022), which did not stop minor-league international signings. The 2022-2026 CBA, ratified March 2022, was in force for most of the period. Pool size was set under the prior system, and the international-draft question stayed open until July 25, 2022. Calling the rules_era CBA_2017_2021 is a judgment call; it could also be classed as CBA_2022_2026.',
   (select id from public.sources where source_key = 'cal:mlb-covid-intl-periods-2020'), (select id from public.rules_eras where rules_era_key = 'INTL_CBA_2017_2021')),
  ('2023', '2023 international signing period (also styled ''2022-23'')', date '2023-01-15', date '2023-12-15', 'CBA_2022_2026', 'First period opening after the international draft was rejected on July 25, 2022. AP refers to its pool as ''2022-23'' (kept at $167M per a side letter).',
   (select id from public.sources where source_key = 'cal:ba-2023-pools'), (select id from public.rules_eras where rules_era_key = 'INTL_CBA_2022_2026')),
  ('2024', '2024 international signing period (MLB.com URL slug uses ''2023-24'')', date '2024-01-15', date '2024-12-15', 'CBA_2022_2026', 'Standard calendar-year window.',
   (select id from public.sources where source_key = 'cal:mlb-top50-2024'), (select id from public.rules_eras where rules_era_key = 'INTL_CBA_2022_2026')),
  ('2025', '2025 international signing period', date '2025-01-15', date '2025-12-15', 'CBA_2022_2026', 'Roki Sasaki, posted Dec 8, 2024, signed in this period: no signings were allowed Dec 15, 2024 - Jan 15, 2025, and he was subject to the 25+/6-year rule.',
   (select id from public.sources where source_key = 'cal:mlb-signing-day-2025'), (select id from public.rules_eras where rules_era_key = 'INTL_CBA_2022_2026')),
  ('2026', '2026 international signing period', date '2026-01-15', date '2026-12-15', 'CBA_2022_2026', 'Opened Jan 15, 2026, with a scheduled close of Dec 15, 2026, which is still in the future as of 2026-10-19. The 2022-26 CBA expires Dec 1, 2026, two weeks before the scheduled close. In June 2026 CBA talks, MLB proposed an international draft ($200M hard pool, minimum age 18) that would start no earlier than Sept 2027 per the MLBPA. Reporting says nothing in the proposals changes this year''s process. No source found on what happens to the Dec 1 - Dec 15 stretch if a lockout begins; the Jan 2022 precedent was that minor-league international signings continued during a lockout. No reporting from Sept-Oct 2026 was found.',
   (select id from public.sources where source_key = 'cal:mlb-signing-day-2026'), (select id from public.rules_eras where rules_era_key = 'INTL_CBA_2022_2026'))
insert into public.source_observations (source_id, subject_table, subject_id, field_name, observed_value, locator, observed_on)
insert into public.fact_resolutions (subject_table, subject_id, field_name, chosen_observation_id, considered_observation_ids, rule, decided_by, rationale)
insert into public.fact_resolutions (subject_table, subject_id, field_name, chosen_observation_id, considered_observation_ids, rule, decided_by, rationale)
